  "fara_magdalena": {
   "name": "Fara św. Marii Magdaleny ze szkołą",
   "parent": "wroclaw",
   "sheets": {
    "wroclaw": {
     "x": 934,
     "y": 1379,
     "n": 4,
     "cx": 959,
     "cy": 1335,
     "r": 23
    }
   },
   "desc": [
    {
     "ch": "II",
     "text": "Wspomniana przez Bogusza: karczmarz „spod Świętej Marii Magdaleny” poi pachołków posłów głogowskich i pokazywał mu ich monetę."
    },
    {
     "ch": "III",
     "text": "Kuncz uczył się w szkole „u Świętej Marii Magdaleny, przy farze”, gdzie słowo „magister” stało „tylko w księgach”; według jego matki sołtysi zza Ślęży noszą teraz łąki na farę zamiast do plebana z Ligoty."
    },
    {
     "ch": "IV",
     "text": "W noc porwania drzwi stoją otworem, a w nawie nocują na słomie chłopi zamknięci w mieście, z klatką gęsi pod filarem. Zapach schnących kożuchów jest „kwaśny jak w owczarni”, a pod sklepieniem wciąż czuć kadzidło z nieszporów."
    },
    {
     "ch": "V",
     "text": "Wspomniana: w karczmach „pod Świętą Marią Magdaleną” szukano Lewka; „u pisarza przy farze” syn Heidenreicha uczy się rachunku; w farze pachniało mokrą wełną w noc po porwaniu."
    },
    {
     "ch": "VI",
     "text": "Z fary biją dzwony na nieszpory, a w czwartek przed św. Tomaszem słychać stamtąd przez ścianę śpiew „O Sapientia”. Kuncz czeka „przy farze pod ścianą od strony cmentarza, gdzie grabarz kuł ziemię tylko w południe”; za farą uliczki prowadzą ku murowi, a przy farze rozchodzą się drogi Dietricha i Kuncza."
    },
    {
     "ch": "VII",
     "text": "Przy farze jest cmentarz z grobem Hanka; w VII.7 Agnieszka odchodzi od bramy zamkowej „w stronę fary środkiem ulicy”."
    },
    {
     "ch": "VIII",
     "text": "Tylko wspomniana: „U ludwisarza przy Świętej Marii Magdalenie jest jeden, co nie słyszy. Od dzwonów ogłuchł.”"
    },
    {
     "ch": "IX",
     "text": "Według młodego zbrojnego po powrocie księcia dzwonili „na farze, u Marii Magdaleny”, a „dzwonnikowi u Marii Magdaleny ręce odpadły”."
    },
    {
     "ch": "XI",
     "text": "Wspomniany: „W szkole przy Świętej Marii Magdalenie uczą czytać i pisać” – do szkoły trzeba polecenia do rektora. W XI.8 odzywają się „dzwony u Świętej Marii Magdaleny i na farze”."
    }
   ],
   "notes": [
    {
     "ch": "III",
     "text": "Przypis 5: szkoła parafialna przy farze wrocławskiej; zgodę na jej założenie, obok szkoły katedralnej, miasto uzyskało w 1267 r."
    }
   ],
   "id": "fara_magdalena"
  },
