  "zamek": {
   "name": "Zamek książęcy z kancelarią",
   "parent": "wroclaw",
   "sheets": {
    "wroclaw": {
     "x": 883,
     "y": 828,
     "n": 6,
     "cx": 877,
     "cy": 800,
     "r": 22
    }
   },
   "desc": [
    {
     "ch": "P",
     "text": "Siedziba aktualnego pana miasta: kancelarie piszą „bez względu na porę roku i na osobę siedzącą akurat na zamku”; książę głogowski „przesiedział na zamku niecały miesiąc”."
    },
    {
     "ch": "II",
     "text": "„Na zachodzie za mostem stał nad wodą nowy zamek księcia z Legnicy”; mur miejski jeszcze tam nie doszedł, „ale dym z zamkowej kuchni szedł wszędzie”."
    },
    {
     "ch": "III",
     "text": "Z okna starego zamku widać „dachy lewego brzegu i dym z kuchni nowego zamku”; obecny książę przeniósł się tam, bo na Ostrowie było „za blisko do biskupa i za dużo nieboszczyka”. Na dziedzińcu zamkowym jest stajnia."
    },
    {
     "ch": "IV",
     "text": "Na Marcina „szło się do zamku” drogą pod murem, obok łaźni. Z kaplicy zamkowej bije dzwon na alarm, z bramy wybiegają zbrojni w kapalinach, a brama „zamknęła się ciężko dwoma skrzydłami, a belka opadła w uchwyty”."
    },
    {
     "ch": "V",
     "text": "Wspomniany: Lewka szukano „w stajniach przy zamku” i „u Żydów przy zamku”."
    },
    {
     "ch": "VII",
     "text": "Z rogu uliczki naprzeciw bramy Dietrich widzi dwóch zbrojnych przy bramie; Agnieszka wychodzi z bramy z pustym koszem, a „za zamkiem” zaczyna się dzielnica żydowska."
    },
    {
     "ch": "XI",
     "text": "Książę „od ośmiu dni siedział na zamku”; od strony zamku przychodzi Kuncz i stamtąd bije pierwszy dzwon, a posłaniec z zamku przynosi nowinę o synu księcia."
    }
   ],
   "notes": [],
   "id": "zamek"
  },
  "laznia": {
   "name": "Łaźnia pod zamkiem",
   "parent": "wroclaw",
   "sheets": {
    "wroclaw": {
     "x": 1092,
     "y": 801,
     "n": 7,
     "cx": 1111,
     "cy": 762,
     "r": 22
    }
   },
   "desc": [
    {
     "ch": "III",
     "text": "„Pod murem zamku, nad samą wodą, parowała łaźnia, bo w poniedziałki grzano.” W drzwiach balwierz w skórzanym fartuchu ostrzy brzytwę na pasku, a spod okapu idzie para „ciepła i pachnąca mokrą brzeziną i rozgrzanym kamieniem”."
    },
    {
     "ch": "IV",
     "text": "Łaźnia stoi „z dołu spod muru, tam gdzie brzeg schodził do wody”, przy drodze pod nowym murem, kilkanaście kroków przed skrętem pod bramę zamkową; konie wiąże się do pali wbitych w brzeg, „tam gdzie latem przybijały łodzie”. Grzano w niej „w poniedziałki, w wigilie i w dni opłacone przez zamek”, a pachniała „mokrą brzeziną, ługiem i rozgrzanym kamieniem”. Nazajutrz widać ją z mostu: drzwi przybite deskami na krzyż, przed nimi plama piasku."
    },
    {
     "ch": "V",
     "text": "Wspomniana: Dietrich myśli o parze w łaźni i o tym, że księcia wzięto z łaźni, „gdzie się właśnie mył”."
    },
    {
     "ch": "XI",
     "text": "Wspomniana: w listopadzie „pod łaźnią” kat pokazywał pachołkom, jak podnieść zabitego."
    }
   ],
   "notes": [],
   "id": "laznia"
  },
