  "dwor_lubiaski": {
   "name": "Dwór opactwa lubiąskiego",
   "parent": "wroclaw",
   "sheets": {
    "wroclaw": {
     "x": 424,
     "y": 1096,
     "n": 14,
     "cx": 381,
     "cy": 1098,
     "r": 23
    }
   },
   "desc": [
    {
     "ch": "VII",
     "text": "Dwór stoi „w uliczce schodzącej ku Odrze, za murem z furtą dla wozów” i „więcej było w nim magazynu niż klasztoru”: pod daszkiem na podwórzu szare bele wełny, pod ścianą stodoły solone skóry pachnące jak przedmieścia garbarskie, przy wadze konwers. Izba brata od rachunków jest tak ciasna, że mieszczą się w niej dwie osoby tylko wtedy, gdy jedna siedzi; na półkach zwoje „jak drwa”, na stole miseczka z denarami i rządek odważników."
    },
    {
     "ch": "VIII",
     "text": "„Dwór Lubiążan”: konwers przy wadze waży sól i czyta kartkę Bogusza, „nie przerywając ważenia soli”. Tu też Dietrich słyszał przed świętami od brata Alojzego pytanie kupca o niemego nowicjusza."
    },
    {
     "ch": "X",
     "text": "Wspomniany: tam w grudniu brat Alojzy nad swoją księgą podał liczbę trzydziestu jeden ocalałych z czterdziestu mnichów."
    }
   ],
   "notes": [
    {
     "ch": "VII",
     "text": "Przypis 5: większe opactwa, zwłaszcza cysterskie, utrzymywały w miastach własne dwory (łac. curia) – składy, w których sprzedawano wełnę, skóry i inne płody klasztornych gospodarstw, a zarazem gospody dla braci w podróży. Lubiąż – najstarsze opactwo cystersów na Śląsku, nad Odrą, ufundowane w XII w. przez Bolesława Wysokiego."
    }
   ],
   "id": "dwor_lubiaski"
  },
  "mlyn_olawa": {
   "name": "Młyn na Oławie",
   "parent": "wroclaw",
   "sheets": {
    "wroclaw": {
     "x": 1455,
     "y": 1795,
     "n": 15,
     "cx": 1500,
     "cy": 1796,
     "r": 23
    }
   },
   "desc": [
    {
     "ch": "IV",
     "text": "Wspomniany przez opata: książę „przełożył rzekę pod wasz mur, żeby miasto miało fosę”, i zburzył młyn opactwa; w zamian opactwo dostało na piśmie „pół młyna, który miasto postawiło niżej”, ale „wody nie widzieliśmy od tamtej pory”."
    }
   ],
   "notes": [
    {
     "ch": "IV",
     "text": "Przypis 10: według kroniki opatów klasztoru na Piasku w 1291 r. Henryk V zburzył młyn opactwa na Oławie w nowym mieście, bo dla umocnienia miasta skierował rzekę innym korytem; w zamian nadał klasztorowi połowę nowo zbudowanego młyna i połowę połowu ryb przy nim, czego klasztor nie zdołał potem wyegzekwować."
    }
   ],
   "id": "mlyn_olawa"
  },
  "piasek": {
   "name": "Opactwo Najświętszej Marii na Piasku",
   "short": "Opactwo na Piasku",
   "parent": "wroclaw",
   "sheets": {
    "wroclaw": {
     "x": 1393,
     "y": 779,
     "n": 16,
     "cx": 1381,
     "cy": 738,
     "r": 23
    },
    "ostrow": {
     "x": 374,
     "y": 965
    }
   },
   "desc": [
    {
     "ch": "P",
     "text": "Opactwo kanoników, na których gruncie stoi szopa; co roku po Wielkanocy „kupowało pergamin na cały rok”, posyłając tego samego kanonika z sakiewką od celerarza. Wieczorem „od Piasku dzwoniono na nieszpory”."
    },
    {
     "ch": "I",
     "text": "Opactwo „Sancta Maria in Arena”, od blisko stu pięćdziesięciu lat kanoników regularnych św. Augustyna, którzy „co dzień wychodzili w świat po dziesięciny i czynsze”; Piasek „należał do obu i do żadnego: do Kościoła jak Ostrów, do świata jak miasto”."
    },
    {
     "ch": "II",
     "text": "Procesja św. Jadwigi przechodzi przez Piasek do Trzebnicy; w dzień odpustu „na Piasku zrobiło się cicho jak w domu, z którego wszyscy poszli na odpust”. Dietrich zauważa, że łacińska nazwa wyspy jest o jedną literę dłuższa od słowa „plac” (area – arena)."
    },
    {
     "ch": "IV",
     "text": "Wspomniane: z fary Dietrich nie słyszy dzwonu na kompletę z Piasku."
    },
    {
     "ch": "V",
     "text": "Wspomniane: muł „jest z Piasku, więc liczy”; opactwo ma jedną wieś pod Ścinawą i trzy pod Miliczem; Dzierżko pyta: „Czyj jest Piasek.”"
    },
    {
     "ch": "VI",
     "text": "W tych scenach tylko jako cel i punkt wyjścia: Kuncz i Dietrich przychodzą „z Piasku”, a wdowa pyta, czy ma „nieść skrzynię na Piasek pod pachą”."
    },
    {
     "ch": "VII",
     "text": "Heinczek przychodzi „na Piasek” z zaproszeniem od ojca i odchodzi, „zanim furtian zdążył mu dać chleba”."
    },
    {
     "ch": "X",
     "text": "W rozdz. X tylko punkt odniesienia: Dietrich porównuje z nim układ spalonego klasztoru („Tak zbudowano Piasek”) i drewniany kościół w Głuszycy, który „cały zmieściłby się w prezbiterium na Piasku”."
    },
    {
     "ch": "XI",
     "text": "Tu w Popielec opat posypuje popiołem tonsury kanoników; popiół spalono w kuchni z zeszłorocznych palm. Żona Hermana mówi, że „na Piasku palą oszczędnie”, a Dietrich, że „na Piasku mięsa nie je się nigdy”."
    }
   ],
   "notes": [
    {
     "ch": "II",
     "text": "Przypis 6 (fragment): nazwa opactwa na Piasku, Sancta Maria in Arena, przeszła na Wrocław z Padwy, gdzie macierzysty kościół kanoników stał na miejscu rzymskiej areny; area (plac, podwórze) i arena (piasek) to dwa różne słowa, a ich skojarzenie jest domysłem Dietricha, nie etymologią."
    },
    {
     "ch": "XI",
     "text": "Przypis 17: popiół na Środę Popielcową otrzymywano ze spalenia gałązek poświęconych w Niedzielę Palmową poprzedniego roku; w Europie Środkowej zamiast palm używano gałązek wierzby."
    }
   ],
   "id": "piasek"
  },
  "katedra": {
   "name": "Katedra św. Jana Chrzciciela",
   "parent": "ostrow",
   "sheets": {
    "wroclaw": {
     "x": 1793,
     "y": 826,
     "n": 17,
     "cx": 1852,
     "cy": 835,
     "r": 23
    },
    "ostrow": {
     "x": 1431,
     "y": 1087
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "Dzwony biją z katedry, „starszej od wszystkiego wokół i nowszej zarazem”: „Od zachodu stał przysadzisty kamień, od wschodu wysokie, jasne prezbiterium z cegły, zaczęte jeszcze przez pierwszego biskupa Tomasza”; w katedrze leży biskup Tomasz II, przy niej jest szkoła, w której uczył się pleban Pełka."
    },
    {
     "ch": "II",
     "text": "Widziana z furty: „Na wschodzie za drugim mostem stała katedra, a przy niej dwór biskupi.”"
    },
    {
     "ch": "III",
     "text": "„Za katedrą obszczekały ich spod muru kurii dwa brytany kanoników.”"
    },
    {
     "ch": "VI",
     "text": "W sobotę suchych dni Ostrów „od świtu był pełen kleryków z całej diecezji”; w katedrze biskup Jan siedzi „w białej infule na faldystorium przed ołtarzem” i wyświęca stopień po stopniu. Dietrich stoi „z tyłu przy filarze”, Dorota przy balustradzie."
    },
    {
     "ch": "VII",
     "text": "Tylko wzmianka: biskup Tomasz „od półtora roku leżał w katedrze”."
    }
   ],
   "notes": [
    {
     "ch": "VI",
     "text": "Przypisy 12–13: soboty suchych dni były terminami święceń; święcenia niższe i wyższe udzielano podczas mszy, między czytaniami."
    }
   ],
   "id": "katedra"
  },
  "dwor_biskupi": {
   "name": "Dwór biskupi",
   "parent": "ostrow",
   "sheets": {
    "wroclaw": {
     "x": 1624,
     "y": 866,
     "n": 18,
     "cx": 1604,
     "cy": 912,
     "r": 23
    },
    "ostrow": {
     "x": 965,
     "y": 1215
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "Obok niego stoi dom, w którym urzęduje oficjał."
    },
    {
     "ch": "II",
     "text": "„Był szary i niski i rozległy jak zwierzę przywarte do ziemi i udające kamień.” W piątek „pachniał rybą” od samej bramy, bo przez dziedziniec niesiono ryby do kuchni; przy stajni stało sześć obcych koni w derkach posłów głogowskich."
    },
    {
     "ch": "III",
     "text": "Wspomniany: w dworze biskupim odźwierny chował za pazuchę głogowską monetę; w kancelarii biskupiej siedzi teraz dawny pisarz książęcy Mikołaj z Ołbina."
    },
    {
     "ch": "IV",
     "text": "Wspomniany: tam, „na ławie przy sieni”, Dietrich widział wcześniej rajcę prostującego paznokciem brakteat."
    },
    {
     "ch": "V",
     "text": "Wspomniany: Dietrich znał notariusza Piotra z widzenia „z października, z dworu biskupa”."
    },
    {
     "ch": "VI",
     "text": "Tylko wzmianka: „odpis u biskupa” mówi, że testament spisano w wigilię św. Jana."
    }
   ],
   "notes": [],
   "id": "dwor_biskupi"
  },
