  "swiety_krzyz": {
   "name": "Kolegiata Świętego Krzyża (w budowie)",
   "short": "Święty Krzyż",
   "parent": "ostrow",
   "sheets": {
    "wroclaw": {
     "x": 1604,
     "y": 736,
     "n": 21,
     "cx": 1594,
     "cy": 698,
     "r": 23
    },
    "ostrow": {
     "x": 910,
     "y": 870
    }
   },
   "desc": [
    {
     "ch": "P",
     "text": "„Nieboszczyk książę zaczął świętemu stawiać kościół na Ostrowie, do spółki z Krzyżem Świętym, w podzięce za zgodę z biskupem” (świętemu Bartłomiejowi, patronowi pergaminiarzy). „Budowano go nadal, bez pośpiechu; fundator leżał w nim trzeci rok tymczasowo, bo tak sobie zapisał.”"
    },
    {
     "ch": "I",
     "text": "„Bliżej starego zamku rosły z rusztowań dwa kościoły Świętego Krzyża, jeden na drugim. Dolny stał już pod dachem, górny otwierał się w niebo”; na deskach krzyczą murarze, w dołach syczy wapno, a w dolnym leży tymczasowo fundator."
    },
    {
     "ch": "II",
     "text": "Fundacja zmarłego księcia; w jej chórze leży Henryk Prawy, według testamentu „do czasu”. Wokół rusztowania, murarze krzyczą „po polsku i po niemiecku”, w dołach syczy wapno, a „ceglany pył osiadał na wszystkim rdzawym nalotem”."
    },
    {
     "ch": "III",
     "text": "Pisarze kancelarii mają tu stalle i chodzą na nieszpory („Na nieszpory idziemy do Krzyża”); tu leży nieboszczyk książę i tu zaniesiono jego łoże. Na budowie murarz „zawieszony na linie pod gzymsem”, z rusztowań sypie się ceglany pył."
    },
    {
     "ch": "IV",
     "text": "Z kościoła dochodzi „śpiew niski i nierówny, bo śpiewało niewielu” — modlitwa za księcia; „Na rusztowaniach przy kościele nie było murarzy. Wapno w dołach zamarzło.”"
    },
    {
     "ch": "V",
     "text": "Wspomniany: ciało zmarłego księcia Henryka „od trzech lat leży w chórze Świętego Krzyża tymczasowo”."
    },
    {
     "ch": "XI",
     "text": "Kościół fundacji zmarłego księcia Henryka, który leży tam „pod kamienną płytą w prezbiterium”; w odwilży płyta jest mokra, kanonicy Świętego Krzyża wycierają ją co rano płótnem, a kobiety z Ostrowa przychodzą patrzeć. W kapitule tego kościoła zasiada protonotariusz."
    }
   ],
   "notes": [
    {
     "ch": "P",
     "text": "Przypis 9 (skrót): kolegiata Świętego Krzyża i świętego Bartłomieja, ufundowana przez Henryka IV w 1288 r. jako wotum po zakończeniu sporu z biskupem Tomaszem II; dolny kościół nosi wezwanie św. Bartłomieja; testament księcia przewidywał w niej pochówek tymczasowy, do czasu ukończenia innej fundacji, której nigdy nie ukończono."
    }
   ],
   "id": "swiety_krzyz"
  },
  "stary_zamek": {
   "name": "Stary zamek i niedokończony kościół",
   "parent": "ostrow",
   "sheets": {
    "wroclaw": {
     "x": 1520,
     "y": 655,
     "n": 22,
     "cx": 1470,
     "cy": 618,
     "r": 23
    },
    "ostrow": {
     "x": 600,
     "y": 560
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "Punkt odniesienia na Ostrowie: kościoły Świętego Krzyża stoją „bliżej starego zamku”."
    },
    {
     "ch": "II",
     "text": "Stoi na końcu wyspy, „za wałem i murem”; tu urodził się Prawy, „a teraz nie mieszkał w nim nikt poza strażą”. W bramie stoją ludzie księcia z Legnicy w kapalinach i z włóczniami. Dietrich zastanawia się, czy to jest „stary plac” ojca zmarłego z testamentu – zamek „z murem i z bramą i ze strażą”, a nie plac."
    },
    {
     "ch": "III",
     "text": "Od środka „większy, niż się wydawał z drogi, i bardziej martwy”: studnia z ceglaną cembrowiną i zmurszałym wiadrem bez liny, stajnia z otwartymi wrotami, kuźnia z zimnym paleniskiem, murowane palatium; „Niczego nie brakowało i niczego nie używano.” W bramie dwóch strażników w kapalinach, a brama zamyka się „z jękiem zawiasu nieoliwionego od lat”. Tu zostały skrzynie nieboszczyka."
    },
    {
     "ch": "IV",
     "text": "Po porwaniu stoi pusty, „jeśli nie liczyć straży”; przy bramie pełni straż rudy Wawrzek. Wzdłuż muru na północ, naprzeciw kaplicy, sterczą kikuty przypór, a w trawie leżą kamienie „z trzema kreskami i krzyżykiem”."
    },
    {
     "ch": "V",
     "text": "Wspomniany w żądaniu Głogowa: „na starym placu jego ojca, na zamku, w którym się urodził” ma stanąć klasztor cysterek, „sto mniszek i dwudziestu zakonników, i szpital”. Heidenreich: „Stary zamek na Ostrowie jest książęcy”."
    }
   ],
   "notes": [],
   "id": "stary_zamek"
  },
