  "most_piaskowy": {
   "name": "Most Piaskowy",
   "parent": "wroclaw",
   "sheets": {
    "wroclaw": {
     "x": 1290,
     "y": 905
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "Most, przez który sołtys musiałby nieść list („mam go nieść kanonikom przez most”) i na którym znikają wracający chłopi z Ligoty."
    },
    {
     "ch": "II",
     "text": "Most z Piasku na lewy brzeg, na zachód od furty; za nim stoi nad wodą nowy zamek."
    },
    {
     "ch": "III",
     "text": "„Za mostem Piaskowym” wóz z cegłą na nowy mur ochlapał Dietrichowi rokietę do kolan; tym mostem wraca z zamku na Piasek."
    },
    {
     "ch": "IV",
     "text": "Rano po nocy w farze: „Na moście nie było mgły. Było jasno, ostro i pusto.” Z mostu widać łaźnię, a z bramy gospodarczej opactwa widać idącego po nim człowieka."
    },
    {
     "ch": "VI",
     "text": "Drewniany most między Piaskiem a miastem: Dietrich idzie nim „między jednym a drugim skrzypnięciem desek”. W VI.6 wraca z katedry do miasta „przez oba mosty”."
    },
    {
     "ch": "VII",
     "text": "Syn postrzygaczki „niósł ją przez most na czole”. W VII.6 Kuncz stoi „na moście, w miejscu, gdzie kończyła się ziemia opactwa, a zaczynała rzeka”, na zmarzniętych deskach; Odrę pod lodem słychać tylko przy filarach."
    },
    {
     "ch": "IX",
     "text": "Most na Odrze przy Piasku z oblodzonymi deskami, które zgrzytają pod kopytem; „woda pod lodem odzywała się tylko przy filarach, głucho”. W przedświcie z mostu widać Ołbin i wierzby „na drugim brzegu”."
    },
    {
     "ch": "XI",
     "text": "Droga z Piasku na Rynek: „Poszli przez most Piaskowy na Rynek”."
    }
   ],
   "notes": [],
   "id": "most_piaskowy"
  },
  "most_tumski": {
   "name": "Most Tumski",
   "parent": "ostrow",
   "sheets": {
    "wroclaw": {
     "x": 1490,
     "y": 764
    },
    "ostrow": {
     "x": 570,
     "y": 930
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "„Most z Piasku na Ostrów był drewniany, krótki i rozkołysany. Deski chodziły na nim pod stopą jak luźne zęby”; Dietrich przechodzi nim codziennie. Pod nim Odra, „między poręczami dryfowało babie lato”."
    },
    {
     "ch": "II",
     "text": "„Drugi most”, na wschód od furty, łączący Piasek z Ostrowem; notariusz oficjała przyjeżdża nim „od Ostrowa”, a po drugiej stronie wody rosną wierzby. Wracając od biskupa, Dietrich słyszy, jak „deski grały pod stopami jak zawsze”."
    },
    {
     "ch": "III",
     "text": "Kuncz czeka „przy moście na Ostrów”, chucha w palce i drepcze w miejscu; pod deskami Odra płynie „ciemna i gładka”, a w trzcinach ma już skórkę lodu."
    },
    {
     "ch": "IV",
     "text": "Droga Dietricha z Piasku na Ostrów; odchodząc od bramy starego zamku, Dietrich idzie „nie ku mostowi”, lecz wzdłuż muru na północ."
    },
    {
     "ch": "VI",
     "text": "Tylko pośrednio: z katedry do miasta Dietrich idzie szybko „przez oba mosty”, bo w grudniu mało światła."
    }
   ],
   "notes": [],
   "id": "most_tumski"
  },
