  "a_kosciol": {
   "name": "Kościół Najświętszej Marii Panny",
   "parent": "piasek",
   "sheets": {
    "opactwo": {
     "x": 915,
     "y": 716,
     "n": 1,
     "cx": 915,
     "cy": 716,
     "r": 28
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "„Kościół na Piasku był stary i szary, z dwiema wieżami od zachodu, i miał w sobie szew”: prezbiterium przedłużone w cegle. Leży pod izbą z przywilejami; wieczorem przez uchylone drzwi słychać ostatni psalm nieszporów."
    },
    {
     "ch": "VII",
     "text": "Tylko jedno zdanie: na pasterce brat, który zawsze śpiewał o pół tonu za nisko, zaśpiewał „Puer natus” o pół tonu za nisko i nikt go nie poprawił."
    }
   ],
   "notes": [],
   "id": "a_kosciol"
  },
  "a_portal": {
   "name": "Portal z tympanonem fundacyjnym",
   "parent": "piasek",
   "sheets": {
    "opactwo": {
     "x": 647,
     "y": 716,
     "n": 2,
     "cx": 647,
     "cy": 716,
     "r": 31
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "„W półkolu kamienia nad drzwiami siedziała na tronie Najświętsza Panna z Dzieciątkiem”, przed nią klęczą kobieta i chłopiec i podają jej kościół „mały jak szkatułka”; wokół biegnie wiersz o Marii, żonie Piotra, i jej synu Świętosławie. W literach siedzi porost, brzegi pękają; to „najstarszy dokument opactwa i jedyny, którego nie trzymano w skrzyni”."
    }
   ],
   "notes": [
    {
     "ch": "I",
     "text": "Przypis 2: „Tympanon fundacyjny – Kamienna płaskorzeźba z połowy XII w. z kościoła NMP na Piasku, przedstawiająca Marię, żonę Piotra Włostowica, i jej syna Świętosława ofiarujących kościół Matce Boskiej. Zachowana do dziś.”"
    }
   ],
   "id": "a_portal"
  },
  "a_prezbiterium": {
   "name": "Prezbiterium przedłużone w cegle",
   "parent": "piasek",
   "sheets": {
    "opactwo": {
     "x": 1373,
     "y": 716,
     "n": 3,
     "cx": 1373,
     "cy": 716,
     "r": 28
    }
   },
   "desc": [
    {
     "ch": "I",
     "text": "„Kilkadziesiąt lat temu przedłużono mu prezbiterium o dziesięć kroków na wschód, w cegle”; w jednym miejscu „kończył się ciosany kamień i zaczynała czerwona cegła, udająca, że zawsze tu była”."
    },
    {
     "ch": "III",
     "text": "W czasie komplety kwik świni dochodzi „przez mur i przez okna chóru”, a brat śpiewający od dwudziestu lat o pół tonu za nisko pierwszy raz trafia w dźwięk."
    }
   ],
   "notes": [],
   "id": "a_prezbiterium"
  },
