  "sroda": {
   "name": "Środa",
   "sheets": {
    "slask": {
     "x": 914.3,
     "y": 878.6
    }
   },
   "approx": "Środy nie ma na mapie autora (tylko strzałka „ku Środzie i Głogowowi” na planie Wrocławia). Znacznik stoi w jej rzeczywistym położeniu.",
   "desc": [
    {
     "ch": "V",
     "text": "Pierwszy nocleg poselstwa: „Karczma była pełna i gospodarz dał im jedną izbę na wszystkich, z dwoma łóżkami i ławą”; rycerzowi łóżko, rajcom łóżko, reszcie ława i słoma, przy kaganku."
    },
    {
     "ch": "XI",
     "text": "Wspomniana: w karczmie w Środzie Dietrich obrócił płaszcz Hermana szwem do kaganka i orzekł, że sukno jest z Gandawy, nie z Ypres."
    }
   ],
   "notes": [
    {
     "ch": "V",
     "text": "Przypis 6: Środa Śląska (niem. Neumarkt), jedno z najstarszych miast lokowanych na Śląsku; jej prawo, zwane średzkim, było odmianą prawa magdeburskiego."
    },
    {
     "ch": "XI",
     "text": "Przypis 7: Środa Śląska, miasto na trakcie z Wrocławia do Legnicy i Głogowa; tam nocowało poselstwo w drodze do Głogowa w grudniu 1293 r. (rozdz. V)."
    }
   ],
   "id": "sroda"
  },
