  "vallis_silens": {
   "name": "Dolina Cicha, spalone opactwo św. Wawrzyńca",
   "short": "Dolina Cicha",
   "sheets": {
    "slask": {
     "x": 801,
     "y": 1296
    }
   },
   "approx": "Opactwa nie ma na mapie autora. Według książki leży „pod Siwą Kopą, nad potokiem, ze trzy staje od Głuszycy”, w górze doliny nad wsią.",
   "desc": [
    {
     "ch": "VII",
     "text": "Opactwo cystersów pod wezwaniem św. Wawrzyńca „w górach, na ziemi księcia Bolka”, które „cztery lata temu, zimą, spłonęło do gruntu razem z hutą i skryptorium, z opatem i przeorem”; kronikarz w Henrykowie zapisał to jako karę Bożą. Brat Alojzy wspomina je jako „góry”: opat liczył tam wszystko, a kancelarie przysyłały skóry do zmywania."
    },
    {
     "ch": "VIII",
     "text": "W tym rozdziale bez nazwy: „opactwo w górach”, które brało od kupca aurypigment „beczkami” i którego „już nie ma”; klasztor, w którym „przed pożarem” miał być nowicjusz, „który nie mówi i który słyszy”."
    },
    {
     "ch": "IX",
     "text": "Cysterski klasztor świętego Wawrzyńca w Dolinie Cichej, który w 1289 r. wykazywał biskupowi, że żyje „z pracy rąk”, m.in. ze zmywania skór przysyłanych przez kancelarie; spłonął w noc po świętej Agnieszce, jak wynika z rachuby Dietricha. Według Bartka stał „Pod Siwą Kopą, nad potokiem”, a na pogorzelisku został „kamienny Wawrzyniec, czarny, i ruszt przy nim”."
    },
    {
     "ch": "X",
     "text": "Cysterskie opactwo św. Wawrzyńca „w górach, zwane Doliną Cichą”, które według zapiski z Henrykowa spłonęło w noc po św. Agnieszce 1290 r. „z hutą, ze skryptorium i z całym dobytkiem”. Zimą 1294 zostały mury bez dachów, poczerniałe do wysokości ognia; nad bramą, w niszy, czarny kamienny św. Wawrzyniec z rusztem, obsiadany przez wrony. Wokół krużganka zwykły porządek: kościół (nawa na 41 kroków Dietricha, 43 Sulka), od wschodu kapitularz ze skryptorium, obok skryptorium izba z żelaznymi obręczami beczek i popiołem po pergaminie, przy refektarzu kamienna misa do mycia rąk, w wirydarzu studnia zawalona kamieniami; za wschodnim murem ruiny huty szkła."
    },
    {
     "ch": "XI",
     "text": "Wspomniane: cysterskie opactwo w górach, spalone „w noc po świętej Agnieszce”; według rachunku posłanego biskupowi w grudniu 1289 r. cystersi zmywali tam skóry przysyłane przez kancelarie „po trzy denary od sztuki”."
    }
   ],
   "notes": [
    {
     "ch": "VII",
     "text": "Przypis 13: „Vallis Silens – (łac.) „Dolina Cicha”. Nuncius non rediit – „posłaniec nie wrócił”.”"
    },
    {
     "ch": "IX",
     "text": "Przypis 4: „Vallis Silens… nuncius non rediit – (łac.) »Dolina Cicha… posłaniec nie wrócił«. Opis pakietu w stosie niezałatwionych pism biskupa Tomasza II.”"
    },
    {
     "ch": "X",
     "text": "Przypis 3: wspomnienie św. Agnieszki przypada 21 stycznia; w 1290 r. była to sobota, pożar wybuchł więc w nocy z 21 na 22 stycznia."
    },
    {
     "ch": "XI",
     "text": "Przypis 2: wspomnienie św. Agnieszki przypada 21 stycznia; opactwo spłonęło w nocy z 21 na 22 stycznia 1290 r."
    }
   ],
   "id": "vallis_silens"
  },
  "vallis_silens_huta": {
   "name": "Huta szkła w ruinach opactwa",
   "parent": "vallis_silens",
   "desc": [
    {
     "ch": "X",
     "text": "Budowla, „jakiej nie ma w żadnym klasztorze”: długa i niska, o grubych ścianach, które zapadły się do środka razem z dachem. W popiele krople stopionego szkła, zielonkawe i brunatne, a na kamieniach pod resztką okapu twardy żółty osad w odcieniu lodu ze Złotuchy. W najdalszym kącie płytka prostokątna niecka w śniegu, trzy łokcie na dwa, a obok nadpalone belki ułożone w stos. Zapiska z Henrykowa podaje jako przyczynę pożaru „komin w hucie szkła”."
    }
   ],
   "notes": [],
   "id": "vallis_silens_huta"
  },
  "zlotucha_potok": {
   "name": "Potok Złotucha",
   "parent": "gluszyca",
   "desc": [
    {
     "ch": "X",
     "text": "Potok, wzdłuż którego leży wieś; nurt nie zamarza, ale lód przy brzegach jest „żółtawy i zmętniały jak stary wosk”. Nazwę podał chłopak z sankami. W górze doliny, pod murami spalonego opactwa, potok płynie „głęboko w jarze”, a ten sam żółty odcień ma twardy osad w ruinach huty szkła."
    }
   ],
   "notes": [],
   "id": "zlotucha_potok"
  },
