   "desc": [
    {
     "ch": "IX",
     "text": "Niska i długa karczma „przy drodze za Świdnicą, w miejscu, gdzie gościniec zaczynał się piąć pod górę”, kryta słomą „czarną od dymu”; w środku „ciepło jak w piekarni i duszno jak w oborze”, za przepierzeniem dwie krowy i koza. W zapusty gra piszczałka, tańczą parobcy, przy stole siedzą woźnice, kramarz i drwale; nocuje tu furman z wozem soli."
    },
    {
     "ch": "X",
     "text": "Wspomniana: tam Sulek i Dietrich usłyszeli o kupcu na gniadym koniu, który przed Bożym Narodzeniem pytał o chłopca, co nie mówi, i płacił „grubą monetą”; tam furman radził modlić się za wizytatora pod murami opactwa; parobek „spod Świdnicy” szorował w śniegu czarną motykę pożyczoną kupcowi."
    }
   ],
   "notes": [],
   "id": "karczma_trakt"
