   "summary": "Dietrich wypytał plebana Pełkę, jak przepisywał list, a od Bogusza usłyszał, że Ligota daje trzydzieści maldratów wielkiej dziesięciny z dwudziestu łanów, czyli półtora z łanu, co pasowało do wersji wsi. W odpisie datowanym na 1272 r. zatrzymała go końcowa formuła „In robur perpetue firmitatis”, której w dwunastu dokumentach kancelarii biskupa Tomasza II ze skrzyni nie było przed 1279 r.; gdy Bogusz ogłosił chłopom, że magister zarzuca im fałszerstwo, Dietrich zaprzeczył i podyktował plebanowi krótki list, a ręka plebana sama dopisała tę formułę, wyuczoną w szkole przy katedrze. Dietrich nie wniósł o fałsz: sprawa miała iść do oficjała, wieś miała okazać oryginał przed sądem biskupim, a krowy zostały w opactwie.",
   "quote": "Pachniało świeżym atramentem, galasem, kwaśno i ostro jak niedojrzałe jabłko.",
