   "summary": "Po obiedzie w refektarzu Dietrich przeszedł przez dormitorium do swojej komory i zaczął pismo do oficjała na cienkiej cielęcej skórze, kupionej wiosną od pergaminiarza spod Piasku za pół ceny, bo była z cielęcia, „którego nikt nie zarżnął”. W brudnopisie nazwał odpis „falsam”, ale przekreślił to słowo tak, by dało się je przeczytać, i napisał obok, że odpis jest niewierny co do formy, a co do rzeczy niepewny bez oryginału. Czystopis na owczej skórze, datowany „w piątek po świętym Mateuszu”, prosił oficjała o nakazanie wsi okazania oryginału, a zajęte bydło zostawiał do tego czasu w opactwie.",
