   "summary": "Po nonie Dietrich przyniósł pismo do opata Świętosława, który nosił pieczęć opactwa na piersi. Opat przyznał, że w 1272 r. zasiadał w kapitule, lecz nie pamięta sprawy Ligoty, i zauważył, że oficjał jest człowiekiem biskupa Jana, który przez ćwierć wieku pisał listy w kancelarii obu Tomaszów, więc może zapytać, skąd opactwo wie, kiedy ta kancelaria zmieniła formułę; mimo to kazał zostawić uzasadnienie i sam zapieczętował pismo. Zapytany, czego właściwie chce, Dietrich nie odpowiedział, a opat oddał mu pismo ze słowami: „Dwie krowy, magistrze”.",
