   "summary": "Biskup Jan powiedział Dietrichowi, że klauzula o wiecznej mocy, obecna w dokumentach biskupa Tomasza od 1279 roku, nie pochodzi od nowego pisarza, lecz od kogoś, kto już był w kancelarii i dostał wtedy do pisania końce – Dietrich zrozumiał, że chodzi o samego biskupa, i o nic nie zapytał. Następnie biskup pokazał mu przywieziony przez Głogowian uwierzytelniony odpis testamentu Henryka Prawego, list księcia głogowskiego z prośbą o zatwierdzenie fundacji klasztoru cysterek „na starym placu” ojca zmarłego oraz przywilej Prawego dla biskupstwa, wystawiony tego samego dnia co testament, w wigilię św. Jana 1290. Na koniec zapytał, co by odpowiedzieli, gdyby ktoś kiedyś zapytał, czy testament był prawdziwy, i przerwał Dietrichowi: „Nie teraz, magistrze. Jeszcze nikt nie pyta.”",
