   "summary": "Lutek otworzył skrzynie i zostawił im latarnię i klucze; przez siedem dni, od prymy do nieszporów, Dietrich i Kuncz czytali w piwnicy pod palatium pięć skrzyń nieboszczyka: listy przychodzące, nadane mu przywileje, wygładzone tabliczki i formularz, w którym nie było wzoru testamentu. Znaleźli rachunek kancelarii z czerwca 1290 pisany ręką starego Jana, z wydatkiem na świece w wigilię św. Jana, „bo pisano w nocy”, i na kota do piwnicy, ale bez słowa o testamencie. Kuncz wyliczył pisarzy kancelarii z 1290 roku, wśród nich zmarłego zeszłej zimy Hanka, którego wdowa Agnieszka wciąż przepisuje dla kancelarii; w sobotę przed Wszystkimi Świętymi zamknęli skrzynie.",
