   "summary": "Agnieszka odesłała Jutkę na górę i przy świecy postawiła warunek: skrzynia wyjdzie z domu cała albo wcale, na kwit i na przechowanie, dopóki Dietrich nie wystawi jej pisma, kto dziedziczy po żonatym kleryku, bo dom stoi pod prawem miejskim, a pismo magistra, który w Głogowie odpowiadał za miasto, ława przeczyta. Dietrich przyznał, że prawo o tym milczy, i zażądał najpierw dowodu, że Hanko był klerykiem; Agnieszka obiecała na sobotę to, co ma o jego święceniach, i zamknęła skrzynię na klucz. Przy farze Kuncz powiedział, że w sobotę nie może przyjść z powodu święceń, i zapytał, czy magister przyjdzie.",
