   "summary": "W sobotę suchych dni Dietrich patrzył w katedrze, jak biskup Jan udziela święceń i podaje Kunczowi do dotknięcia księgę, po czym przez oba mosty poszedł do Agnieszki. Wdowa pokazała mu zapiskę Hanka o przyjęciu tonsury w 1277 r., złociła przy nim inicjał B psałterza, a potem napisała kwit: skrzynię z 43 skórami, 9 zwojami kwitów i wzornikiem liter oddaje Dietrichowi w depozyt, a on przyrzeka jej pismo o spadku po żonatym kleryku; świadkiem była Gertruda. Porównując przez szkła jej pismo z ręką Hanka i pytając, komu to służy, Dietrich uznał – na domniemaniu, bez dowodu – że datę na rasurze dopisała ona, i postanowił wziąć skrzynię teraz, a pismo odłożyć.",
