   "summary": "W dzień św. Tomasza Bogusz przyszedł do komory Dietricha z pytaniem od opata, czy czeladź może jeść wieprzowinę w Boże Narodzenie, które wypada w piątek; Dietrich wyłożył, że może, a celerarz przekazał od opata, że „depozyt się oddaje”, i poprosił, by magister wyjaśnił w dworze lubiąskim spór o zapłatę za skóry na antyfonarz i zapytał o farbę do inicjałów zamiast złota. Potem Dietrich rozłożył ze skrzyni skórę z listą świadków i policzył na palcach pięciu ludzi z izby umierającego księcia, których nie można już o nic zapytać: zmarłego biskupa Tomasza, ściętego latem w Legnicy Pakosława, pochowanego po Gromnicznej Hanka, zbiegłego albo wygnanego medyka i przekreślone imię. Postanowił wypytać grabarza, sąsiadów i kancelarię, na co umarł Hanko.",
