   "summary": "We wtorek przed Bożym Narodzeniem Dietrich poszedł do dworu opactwa lubiąskiego, gdzie cysterski brat od rachunków, który przedstawił się jako brat Alojzy, zapewnił, że Piasek zapłacił za skóry z Michała, i podpisał kwit spisany przez Dietricha. Zapytany o farbę do inicjałów polecił auripigmentum od kupca Ortlieba z Pragi, który przyjeżdża na jarmarki i nosi towar także do kancelarii. Sam z siebie opowiedział, że był dawniej w opactwie w górach, które spłonęło; że Ortlieb wypytywał go o nowicjusza, „co nie mówi”, i o składki pisane ręką opata; że prawie cztery lata temu, w noc po św. Agnieszce, wyprowadził trzydziestu jeden z czterdziestu braci i że wizytator biskupa nie wrócił, a nikt go o nic nie pytał.",
