   "summary": "Między świętami Dietrich przyszedł do dworu biskupiego szukać w „prawym” stosie brudnopisów zmarłego biskupa Tomasza minut w sprawie Ligoty; notariusz oficjała wpuścił go do izby przy sieni i poszedł się ogrzać. Ligoty nie znalazł, ale w pakiecie opisanym „Vallis Silens” i „nuncius non rediit” przeczytał list opactwa cystersów z Doliny Cichej, powołujący się na przywileje zakonu, oraz minutę listu biskupa z oktawy Trzech Króli 1290 r., który w sprawie dziesięcin nieoddawanych w całości i „o innych jeszcze sprawach” posyłał tam brata Gedeona jako wizytatora „do wszystkich i każdego z osobna miejsc” klasztoru, choć do domów cysterskich biskupi wizytatorów nie posyłali. Przepisał minutę bez pozwolenia, dopisał na marginesie „quo titulo?” i odłożył pakiet na miejsce.",
