   "summary": "W piątek rano Bogusz z kartką od magistra dowiedział się od konwersa na dworze Lubiążan, że kupiec zwany Praskim siedzi u pergaminiarza nad Odrą poniżej Piasku, i kupił tam od Ortlieba z Pragi dwie uncje aurypigmentu na antyfonarz. Kupiec zważył wrocławskie brakteaty na własnej wadze, kazał dopłacić cztery, wystawił kwit pisany szybką kursywą, a na uwagę, że opactwu w górach sprzedawał taniej, odparł, że tamto brało beczkami i już go nie ma. Przy ważeniu pytał o niemego chłopaka z gór za Świdnicą, który „ma ucho do metalu”, a gdy Bogusz wychodził, zamówił u pergaminiarza z góry martwo urodzone cielęta z wiosennych wycieleń.",
