   "summary": "W izbie pisarskiej nad zakrystią Bogusz pokazał aurypigment armariusowi Eberhardowi, który żałował złota do antyfonarza, i złapał go za rękę, zanim ten oblizał pędzel. Dietrich rozpoznał w kwicie Ortlieba rękę wyuczoną w kancelarii albo w szkole katedralnej, wpisał zakup do rejestru celerarza razem z imieniem sprzedawcy i uznał, że kupiec, który pytał już brata Alojzego o niemego nowicjusza ze spalonego klasztoru, nie uwierzył w śmierć chłopaka. Brat Sulek przyniósł list od Agnieszki: protonotariusz nie da jej więcej roboty, ona przyjdzie we wtorek po prymie obejrzeć swoją skrzynię i czeka na obiecane pismo.",
