   "summary": "W rozmównicy przy furcie, przy bracie Sulku jako świadku, Agnieszka przeliczyła skóry ze skrzyni Hanka, wypomniała Dietrichowi wypytywanie grabarza i sąsiadów o śmierć męża i pokazała na obcinku, jak iluminator zakrywa słowo bielą ołowianą. Na trzydziestej czwartej skórze rozpoznała w polu inicjału N sczerniałą biel położoną jej pędzlem — Hanko coś nią zamalował — i nie pozwoliła Dietrichowi jej skrobać. Zażądała pisma do Gromnicznej, a wychodząc, przeszła trzewikiem po słowie, które Jutka zaczęła pisać patykiem na śniegu pod swoim imieniem.",
