   "summary": "Na Gromniczną przed świtem Dietrich szedł z procesją ze świecami przez krużganek, a po mszy postawił gromnicę w komorze na czystej, wciąż pustej skórze przyciętej pod pismo dla wdowy. Wezwany w południe do ratusza, w izbie rady przejrzał na prośbę rajcy Heidenreicha uchwałę spisaną przez Konrada i kazał zamienić solutio (spłata) na redemptio (wykup jeńca), bo na wykup jeńców Kościół pozwala oddać nawet srebro z ołtarza, i Konrad napisał nowe słowo na rasurze. Po nieszporach pachołek miejski odczytał uchwałę ze stopni ratusza: daninę od domów, kramów i ław, zakaz wywozu srebra i obowiązek zgłoszenia srebrnych naczyń do świętego Macieja.",
   "quote": "Na Rynku po nieszporach było tłoczno, bo w święto kramy stały zamknięte, a ludzie i tak przyszli, żeby stać.",
