   "summary": "Dietrich przyszedł do izby przy sieni w sprawie siana dla krów z Ligoty; notariusz oficjała powiedział, że odpowiedź w sprawie Ligoty będzie po Wielkanocy, a pisma po biskupie Tomaszu, na które nikt nie odpowiedział, idą pod nóż na nową księgę dóbr. Pakiet z Doliny Cichej był już zeskrobany i została po nim kartka „Vallis Silens… nuncius non rediit”, ale ostatnią skórę Dietrich zdążył przeczytać i przepisać: rachunek przeora Bertolda z 1289 roku za zmywanie skór dla kancelarii, z 65 skórami od kancelarii książęcej na świętą Łucję, przy których ktoś postawił na marginesie znak nota, i z adnotacją o przyjęciu w Nysie opatrzoną słowem nil. Po powrocie przez most do furty powiedział bratu Sulkowi, że jedzie w góry.",
   "quote": "Każde pociągnięcie zdejmowało ze skóry wąski pas pisma i zostawiało po sobie smugę jaśniejszą od reszty, a na stół sypały się szare wiórki, zwinięte w rożki jak obierzyny z jabłka.",
