   "summary": "Pierwszego dnia Dietrich jechał na mule, a Sulek szedł obok pieszo, ze Ślężą po lewej ręce przez cały dzień; nocowali na plebanii pod lasem, gdzie stary pleban obejrzał pieczęć listu opata i oddał go, nie rozwijając. Drugiego dnia przed południem, przy moście na Bystrzycy przed Świdnicą, jednouchy celnik zważył wrocławskie brakteaty i zażądał dwóch skojców, a Sulek „przeczytał” mu list opata po polsku, dodając mosty, biskupa i groźbę, więc celnik przepuścił ich bez opłaty. Za mostem Dietrich powiedział, że nie jest od biskupa, a Sulek odparł, że skoro biskup wyparł się go na piśmie, było się czego wypierać.",
