   "summary": "W karczmie za Świdnicą, pełnej zapustnej zabawy, Dietrich zapłacił jednym z głogowskich krążków opata, a karczmarz, nadgryzłszy monetę, opowiedział, że przed Bożym Narodzeniem takim samym płacił obcy kupiec na gniadym koniu, mówiący gładko jak ksiądz na kazaniu, który wypytywał o niemego chłopaka ze spalonego klasztoru, dostał drogę do klasztoru i pożyczył od parobka Maćka motykę, oddaną po dwóch dniach czarną od sadzy. Dietrich nie miał wątpliwości, że był to kupiec z Pragi, i nie znalazł w jego postępowaniu niczego, co nie pasowałoby do kupca. Na koniec do ich ławy przysiadł się furman w kożuchu białym od soli i zapytał, czy jadą do Głuszycy.",
