   "summary": "Bartek od soli, który od czterech zim opowiadał tę historię po karczmach, opisał kanonikom cysterski klasztor świętego Wawrzyńca pod Siwą Kopą, ze trzy staje od Głuszycy: opata z Pragi w zmowie z diabłem, nocne światła i dym, ginące dzieci i wizytatora, który z książęcym pismem przy sercu trzymał drzwi przed diabłami, aż zabrał go ogień. Dietrich pytał, kto to widział, a potem o sól: Bartek przypomniał sobie, że jako pachołek zmarłego Paszka co wtorek woził w góry sól i zapieczętowane worki skór z wrocławskiej kancelarii do zmycia, a na świętą Łucję były dwa ciężkie wory z orłem na sznurku. W nocy Bartek długo nie mógł zasnąć, bo pierwszy raz zastanowił się, od kogo Paszko usłyszał tę historię.",
