   "summary": "Trzeciego dnia droga szła w górę doliną Bystrzycy, między świerkowymi stokami i zaspami, obok dymiących mielerzy węglarzy; Sulek ożywiał się z każdą milą, a Dietrich marzł. Pod wieczór doszli do ostatniej wsi przed lasem, gdzie sołtys Tilo, który twierdził, że pochodzi spod Miśni, przyjął Dietricha jak krewnego i obejrzał pieczęć listu, nie rozwijając go. Po zmroku zajechali dwaj ludzie księcia Bolka w drodze na Rogowiec; młodszy opowiedział, że książę Henryk, wypuszczony podobno na słowo i za zakładników, synów mieszczańskich, wjechał wczoraj koło południa do Wrocławia przy biciu wszystkich dzwonów — Dietrich uświadomił sobie, że stał wtedy na moście na Bystrzycy — a starszy skwitował, że okup stał się teraz długiem.",
