   "summary": "W piątek Dietrich i Sulek poszli pod górę do spalonego opactwa w Dolinie Cichej; Sulek pomodlił się pod poczerniałym posągiem świętego Wawrzyńca nad bramą za brata Gedeona, wysłannika biskupa. Dietrich przemierzył krokami nawę i obszedł ruiny: przy skryptorium znalazł izbę z obręczami beczek i popiołem po pergaminie, ale nigdzie śladu kadzi do zmywania skór, a za wschodnim murem, w ruinie huty szkła, żółty osad na kamieniach i płytką prostokątną nieckę w śniegu obok nadpalonych belek ułożonych w stos, którą uznał za rozkop. Zanotował liczby, pytanie „ubi lavabant?” i słowo „mercator”.",
