   "summary": "Dwa dni po powrocie z gór Dietrich przyszedł do izby rady, gdzie na dwóch okutych skrzyniach leżało srebro znoszone przez mieszczan na wykup księcia. Heidenreich, który chciał usunąć z ugody z Głogowem nowy artykuł o uznaniu ostatniej woli zmarłego księcia, uznał, że do targu wystarczy mu pytanie o sześćdziesiąt pięć skór oddanych przez kancelarię książęcą do zmycia w dzień św. Łucji, pół roku przed testamentem. Gdy Dietrich przyznał, że żyje chłopak z tamtejszej wsi, który był w opactwie, Konrad zapisał na tabliczce „puer, qui fuit in monasterio, vivit. Vidit”, a na prośbę Dietricha dopisał nad wierszem „non legit”.",
