   "summary": "W dzień św. Macieja, ostatni dzień zgłaszania srebra, Dorota przy ławach chlebowych powiedziała Dietrichowi, że oddała pisarzowi miejskiemu jedyną srebrną łyżkę, którą mają jej policzyć przy szosie. Kuncz przyniósł przepisane rachunki kancelarii za maj 1290 r., w których pod wigilią Zielonych Świąt stał zakup dwunastu cienkich skór cielęcych „do testamentu pana”, i opowiedział, że protonotariusz, widząc go przy tej pracy, powiedział tylko „ach”. Dietrich zestawił ten zapis z kupnem wosku do pieczęci wielkiej w czerwcu i z rasurą w miejscu daty na liście świadków ze skrzyni Agnieszki, po czym zabrał rulon.",
