   "summary": "W Popielec rano opat posypał kanonikom tonsury popiołem, a po południu Heidenreich wezwał Dietricha do ratusza, gdzie nowa rada, złożona prawie z tych samych ludzi co stara, uchwaliła szos, podatek od majątku. Dietrich odczytał list notariusza Piotra z Głogowa: zmywanie skór po św. Marcinie nazwano w nim zwyczajem każdej kancelarii, a o młodzieńcu, który był w klasztorze i „widział”, napisano, że jeśli jest świadkiem, niech zezna przed stronami. W liście zabrakło zastrzeżenia, że chłopak nie czyta; Konrad nie pamiętał, czy je przepisał, bo tabliczkę już zatarł, a Heidenreich nie chciał tego prostować, bo dopóki Głogów nie wie, co chłopak widział, boi się, że widział wszystko.",
   "quote": "Wstając z kolan, poczuł jej resztkę osypującą mu się z tonsury za kołnierz.",
