   "summary": "W czwartek po Popielcu Jakusz wezwał Dietricha do skarbca Piasku, gdzie Heidenreich prosił opata o kościelne srebro na wykup księcia, powołując się na słowa Dietricha o świętym Ambrożym. Dietrich potwierdził, że prawo na to pozwala, ale za zgodą biskupa; opat nie chciał pytać biskupa, odmówił krzyża z relikwią, kadzielnic i codziennego kielicha i oddał rajcy dwa kielichy z patenami, które stały osobno na lnianej serwecie. Bogusz wymógł na Heidenreichu kwit z pieczęcią rady, a opat powiedział Dietrichowi, że trzyma go dlatego, że ten nie umie napisać inaczej, niż się pisze.",
