   "summary": "Po rozruchach przeciw szosowi ludzie rady przeszukali domy tych, którzy nie zgłosili srebra, i u pieczętarza Wernhera przy ulicy Szewskiej znaleźli w skrzyni pod szatami srebrny tłok pieczęci zawinięty w len z ogarkiem świecy, a jego samego osadzono w wieży. W izbie rady Dietrich rozpoznał w tłoku pieczęć wielką zmarłego księcia Henryka, bez śladu wosku, z kłaczkami lnu w rowkach liter, ale radzie powiedział tylko, że trzymanie tłoka nie dowodzi, że ktoś go użył. Budziwoj przyniósł zgodę księcia, by pieczętarza zapytać „mocniej, niż się zwykle pyta”, i mimo sprzeciwu Dietricha Heidenreich postanowił, że mistrz Lamprecht zapyta go w przyszły czwartek.",
