   "summary": "W piątek po południu Dietrich odwiedził w wieży przy bramie pieczętarza, który powiedział, że trzymał tłok razem z ogarkiem gromnicy „za duszę pana”, co roku w wigilię św. Jana zapala ten ogarek i po śmierci księcia tłoka nie przykładał; na pytanie o piątek przed św. Barnabą, 9 czerwca, nie odpowiedział, powołując się na przysięgę złożoną zmarłemu panu. Przy wyjściu zaprosił Dietricha do swojego domu przy wieży kat miejski, mistrz Lamprecht, który mówił o trzech rodzajach przesłuchiwanych i o tym, że słucha, gdzie łamie się głos. Na koniec poprosił o list polecający dla syna do szkoły przy Świętej Marii Magdalenie, bez słowa o ojcu, a Dietrich odpowiedział, że pomyśli.",
