   "summary": "Nazajutrz po św. Gertrudzie Dietrich przyszedł do izby rady powiedzieć Heidenreichowi, że nie ułoży pytań dla mistrza Lamprechta; mówiono tam o pogłosce z Ostrowa, że płyta na grobie księcia Henryka u Świętego Krzyża się poci, a Budziwoj chciał postawić przy niej pieczętarza, na co Dietrich odpowiedział, że płyta poci się od odwilży. Wtedy zabiły dzwony i posłaniec z zamku oznajmił, że księżna urodziła zdrowego syna. Heidenreich wyliczył, że z dwoma synami księcia to Głogów musi się teraz spieszyć, i postanowił, że pieczętarza przesłuchają nazajutrz.",
